mapper.select:
select * from(
SELECT info.FINPROD_MARKET_ID AS prodId, rul.EFF_DATE AS changeDate, info.PROFIT_TYPE as profitType, '01' changType, rul.YIELD AS prodYield, null as prodBenchmarkRate, null as unitValueTotal, null as unitValue, null as sevenDayRate, nvl(rul.UPDATE_TIME,rul.CREATE_TIME) updatetime FROM FIN_CASH_CALC_RULE rul left JOIN FIN_PRODUCT info on info.FINPROD_ID=rul.FINPROD_ID LEFT JOIN FIN_CASH_INFO B ON rul.CASH_ID = B.CASH_ID WHERE 1=1
and info.FINPROD_TYPE2 in
#{finprodType2,jdbcType=VARCHAR}
AND info.PROFIT_TYPE = '02' and B.CASH_TYPE_1 = '02' AND rul.BRANCH=0 and b.branch = 0 ---取母产品报价 and nvl(rul.UPDATE_TIME,rul.CREATE_TIME) > #{updatetime,jdbcType=TIMESTAMP} union all
select info.FINPROD_MARKET_ID AS PROD_ID, val.VAL_DATE as changeDate, info.PROFIT_TYPE as profitType, '02' changType, null AS prodYield, null as prodBenchmarkRate, val.TOTAL_NET_VALUE as unitValueTotal, val.NET_UNIT_VALUE as unitValue, val.SEVEN_DAY_RATE as sevenDayRate, nvl(val.UPDATE_TIME,val.CREATE_TIME) updatetime from bok_valbal_table_status val LEFT JOIN FIN_PRODUCT info on info.FINPROD_ID = val.FINPROD_ID where info.FINPROD_TYPE2 = 'F16' AND info.PROFIT_TYPE in ('01','03')
and val.NOTICE_STATUS = '1'
and val.CONFIRM_STATUS = '1'
and (val.NOTICE_STATUS is null or val.NOTICE_STATUS != '1') and (val.CONFIRM_STATUS is null or val.CONFIRM_STATUS != '1')
and nvl(val.UPDATE_TIME,val.CREATE_TIME) > #{updatetime,jdbcType=TIMESTAMP}
union all
SELECT info.FINPROD_MARKET_ID AS prodId, rul.EFF_DATE AS changeDate, info.PROFIT_TYPE as profitType, '03' changType, null AS prodYield, rul.rate as prodBenchmarkRate, null as unitValueTotal, null as unitValue, null as sevenDayRate, nvl(rul.UPDATE_TIME,rul.CREATE_TIME) updatetime FROM FIN_BASE_RULE_INFO rul left JOIN FIN_PRODUCT info on info.FINPROD_ID=rul.FINPROD_ID
WHERE 1=1
and info.FINPROD_TYPE2 in
#{finprodType2,jdbcType=VARCHAR}
AND info.PROFIT_TYPE in ('01','03') AND rul.BRANCH=0 and rul.base_rule_type='02' and nvl(rul.UPDATE_TIME,rul.CREATE_TIME) > #{updatetime,jdbcType=TIMESTAMP}
) a where 1=1
and a.prodId in
#{prodid,jdbcType=VARCHAR}

mapper.delete:
delete from CHB_PRD_PERIODYIELD
where PROD_ID=#{prodid,jdbcType=VARCHAR}
and to_char(CHANGE_DATE,'yyyy-mm-dd')=#{changedate,jdbcType=VARCHAR}

begin

	delete from
	CHB_PRD_PERIODYIELD
	where
	PROD_ID=#{dto.prodId,jdbcType=VARCHAR}
	and
	CHANGE_DATE=#{dto.changeDate,jdbcType=TIMESTAMP}

		and FPROD_ID=#{dto.fprodId,jdbcType=VARCHAR}


;end;
